mapper.select:
SELECT FROM
AND #{random} = #{random}
ORDER BY

SELECT a.id, a.create_by AS createBy, a.create_date AS createDate, a.update_by AS updateBy, a.update_date AS updateDate, a.remarks, a.status, a.person_name AS personName, a.warning_type AS warningType, a.warning_content AS warningContent, a.warning_time AS warningTime, a.alarm_record AS alarmRecord, a.alarm_time AS alarmTime, a.trigger_reason AS triggerReason, a.handler, a.handle_time AS handleTime, a.handle_process AS handleProcess, a.handle_status AS handleStatus, a.attachment, a.device_id AS deviceId, a.id_card AS idCard, a.disposal_duration AS disposalDuration, a.x AS x, a.y AS y, a.location AS location, a.area AS area FROM swm_warning_management a WHERE a.id = #{id}
AND a.id_card = #{idCard}
LIMIT 1

SELECT a.id, a.create_by AS createBy, a.create_date AS createDate, a.update_by AS updateBy, a.update_date AS updateDate, a.remarks, a.status, a.person_name AS personName, a.warning_type AS warningType, a.warning_content AS warningContent, a.warning_time AS warningTime, a.alarm_record AS alarmRecord, a.alarm_time AS alarmTime, a.trigger_reason AS triggerReason, a.handler, a.handle_time AS handleTime, a.handle_process AS handleProcess, a.handle_status AS handleStatus, a.attachment, a.device_id AS deviceId, a.id_card AS idCard, a.disposal_duration AS disposalDuration, a.x AS x, a.y AS y FROM swm_warning_management a WHERE a.handle_status = '1'
AND a.person_name LIKE CONCAT('%', #{personName}, '%')
AND a.warning_type = #{warningType}
AND a.warning_content = #{warningContent}
AND a.warning_content != '涓€閿甋OS'
AND a.warning_content != '鑰冨嫟鎵撳崱'
AND a.warning_content != '杩涘叆澶ч棬'
AND a.warning_content in
#{warningContent}
ORDER BY a.warning_time DESC

SELECT count(1) FROM swm_warning_management
handle_status = '1'
and handle_time BETWEEN #{startTime} and #{endTime}
